class MessageModel:public QSqlQueryModel {
public:
 QHash<QString,QColor> colors;
 QVariant data(const QModelIndex& idx,int role=Qt::DisplayRole)const override{
  if(role==Qt::FontRole&&idx.column()==0){QFont font("Consolas",10);font.setBold(true);return font;}
  if(role==Qt::ForegroundRole){if(idx.column()==1||idx.column()==2)return QColor("#c48aff");if(idx.column()==3||idx.column()==5)return QColor("#ffe56b");if(idx.column()==0||idx.column()==6){auto color=colors.value(QSqlQueryModel::data(index(idx.row(),0)).toString());if(color.isValid())return color;}return QColor("#42e6ff");}return QSqlQueryModel::data(idx,role);
 }
 void apply(QString query,const QSqlDatabase& db){base_=query;db_=db;reload();}
 void sort(int column,Qt::SortOrder order)override{column_=column;order_=order;if(!base_.isEmpty())reload();}
private:
 QString base_;QSqlDatabase db_;int column_=-1;Qt::SortOrder order_=Qt::AscendingOrder;
 void reload(){auto query=base_;if(column_>=0){query=query.left(query.lastIndexOf("ORDER BY"))+"ORDER BY "+QString::number(column_+1)+(order_==Qt::AscendingOrder?" ASC":" DESC");}setQuery(query,db_);}
};
void Spectrum::updateIq(const QByteArray& b){
 constexpr int N=1024;if(b.size()<N*2)return;std::vector<std::complex<float>> a(N);
 for(int i=0;i<N;++i)a[i]=std::complex<float>((uchar(b[2*i])-127.5f)/128,(uchar(b[2*i+1])-127.5f)/128)*float(.5-.5*cos(2*std::numbers::pi*i/(N-1)));
 for(int i=1,j=0;i<N;++i){int k=N>>1;for(;j&k;k>>=1)j^=k;j^=k;if(i<j)std::swap(a[i],a[j]);}
 for(int len=2;len<=N;len*=2){auto wlen=std::polar(1.f,float(-2*std::numbers::pi/len));for(int i=0;i<N;i+=len){std::complex<float>w=1;for(int j=0;j<len/2;++j){auto u=a[i+j],v=a[i+j+len/2]*w;a[i+j]=u+v;a[i+j+len/2]=u-v;w*=wlen;}}}
 levels_.resize(N);if(waterfall_.isNull()) {waterfall_=QImage(N,80,QImage::Format_RGB32);waterfall_.fill(Qt::black);}
 if(++waterfallFrames%waterfallStride==0)for(int y=79;y>0;--y)memcpy(waterfall_.scanLine(y),waterfall_.scanLine(y-1),N*4);
 for(int i=0;i<N;++i){float db=20*log10(std::max(1e-8f,std::abs(a[(i+N/2)%N])/512));levels_[i]=db;float p=std::clamp(float((db-bottom)/qMax(1.0,top-bottom)*contrast),0.f,1.f);if(waterfallFrames%waterfallStride==0)waterfall_.setPixelColor(i,0,QColor::fromHsvF(.67-p*.67,1,p));}update();
}
void Spectrum::paintEvent(QPaintEvent*){
 QPainter p(this);p.fillRect(rect(),QColor("#020e20"));int h=height()*2/3;p.setPen(QColor("#20334f"));for(int i=0;i<8;++i)p.drawLine(i*width()/8,0,i*width()/8,h);for(int i=0;i<5;++i){int y=i*h/5;p.drawLine(0,y,width(),y);p.setPen(QColor("#abbcd1"));p.drawText(4,y+14,QString::number(top-i*(top-bottom)/5,'f',0)+" dBFS");p.setPen(QColor("#20334f"));}
 auto marker=[&]{double span=sampleRate/zoom;double bandPixels=bandwidth/span*width();p.fillRect(QRectF(width()/2-bandPixels/2,0,bandPixels,h),QColor(40,150,240,35));p.setPen(QColor("#abbcd1"));for(int i=0;i<5;++i){double f=frequency+(i/4.0-.5)*span;p.drawText(int(i*width()/4.0)-50,h-4,QString::number(f/1e6,'f',6)+" MHz");}p.setPen(QPen(QColor("#ff3030"),2));p.drawLine(width()/2,0,width()/2,height());p.drawText(width()/2+5,18,QString::number(frequency/1e6,'f',6)+" MHz");};
 if(levels_.isEmpty()){p.setPen(Qt::lightGray);p.drawText(rect(),Qt::AlignCenter,"Aucune donnée IQ — spectre en attente");marker();return;}
 int bins=std::max(2,int(levels_.size()/zoom)),first=(levels_.size()-bins)/2;QPainterPath line;for(int j=0;j<bins;++j){int i=first+j;double x=double(j)*width()/(bins-1),y=std::clamp(float((top-levels_[i])/qMax(1.0,top-bottom)),0.f,1.f)*h;if(!j)line.moveTo(x,y);else line.lineTo(x,y);}p.setPen(QColor("#42dcff"));p.drawPath(line);p.drawImage(QRect(0,h,width(),height()-h),waterfall_,QRect(first,0,bins,waterfall_.height()));marker();
}
